content:
Этот аддон позволяет создавать рецепты для мода [Ars Nouveau](https://www.curseforge.com/minecraft/mc-mods/ars-nouveau)

Примечание: Модринт не размещает мод Ars Nouveau, поэтому для работы этого аддона вам необходимо установить сам Ars Nouveau из другого источника.

```js
ServerEvents.recipes(event => {
	event.recipes.ars_nouveau.enchanting_apparatus(
        [
            "minecraft:sand",
            "minecraft:sand",
            "minecraft:sand",
            "minecraft:sand",
        ], // исходные предметы
	    "minecraft:gunpowder", // реагент
	    "minecraft:tnt", // результат
	    1000, // затраты источника
	    // true // сохранить NBT реагента (аналогично рецептам на кузнечном столе)
	);

	event.recipes.ars_nouveau.enchantment(
        [
            "minecraft:sand",
            "minecraft:sand",
            "minecraft:sand",
            "minecraft:sand",
        ], // исходные предметы
        "minecraft:vanishing_curse", // применяемое зачарование
        1, // уровень зачарования
        1000, // затраты источника
    );

	event.recipes.ars_nouveau.crush(
        "minecraft:tnt", // исходный блок
        [{
            item: "minecraft:sand",
            chance: 1
        }] // таблица добычи
        // true // выбрасывать предмет в мир?
    );

    /*
    // это *действительно* работает, но рецепт должен соответствовать допустимому глифу
    // в томе, поэтому на практике его можно использовать только для
    // замены рецепта существующего глифа
    event.recipes.ars_nouveau.glyph(
        "minecraft:tnt", // выходной предмет (глиф)
        [
            "minecraft:sand", 
            "minecraft:gunpowder",
        ], // исходные предметы
        3 // стоимость в опыте
    );
    */

    // доступно через команду `/ars-tome id`, в данном случае `/ars-tome kubejs:not_glow`
  	// это точная копия тома «Ловушка со свечением» из базового Ars Nouveau
    event.recipes.ars_nouveau.caster_tome(
        "Not-Glow Trap", // название,
        [
            "ars_nouveau:glyph_touch",
            "ars_nouveau:glyph_rune",
            "ars_nouveau:glyph_snare",
            "ars_nouveau:glyph_extend_time",
            "ars_nouveau:glyph_light"
        ], // заклинание
        "Не связывает цель и не даёт другим целям эффект Свечения.", // описание
        16718260, // цвет
        {
            "family": "ars_nouveau:default",
            "pitch": 1.0,
            "volume": 1.0
        },
    ).id("kubejs:not_glow")

    event.recipes.ars_nouveau.imbuement(
        "minecraft:sand", // исходный предмет
        "minecraft:tnt", // результат
        1000, // затраты источника
        [
            "minecraft:gunpowder" 
        ] // предметы на пьедестале // необязательно
    )
})
```
